import org.springframework.boot.web.client.ClientHttpRequestFactorySupplier

fun bad() {
    val supplier = ClientHttpRequestFactorySupplier()
}

import org.springframework.boot.web.client.ClientHttpRequestFactorySupplier
import org.springframework.boot.web.client.RestTemplateBuilder

fun bad2(): RestTemplateBuilder {
    return RestTemplateBuilder()
        .requestFactory(ClientHttpRequestFactorySupplier())
}

import org.apache.hc.client5.http.impl.classic.HttpClients
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory

fun good(): HttpComponentsClientHttpRequestFactory {
    val client = HttpClients.custom().build()
    return HttpComponentsClientHttpRequestFactory(client)
}
